import { format, t } from "./i18n.ts"
import type { FieldMeta } from "./meta.ts"
import { toast } from "./toast.tsx"

interface Device {
  id: string
  current: boolean
  created_at: string
  last_seen_at: string
  ip_address: string
  user_agent: string
}

/** The account's routes of the realm that signs in. */
interface Account {
  sessions(): Promise<Device[]>
  endSession(id: string): Promise<void>
  endOtherSessions(): Promise<void>
  changePassword(change: { current_password?: string; new_password: string }): Promise<void>
  changeEmail(change: { email: string; redirect?: string }): Promise<void>
  confirmEmail(token: string): Promise<void>
}

export const account = () => api.identity[realmKey] as unknown as Account

/**
 * Runs what changes the account; when the API asks for a recent sign-in
 * (reauthentication_required, a sign-in of the last minutes), offers to
 * sign in again and come back here.
 */
export function useSensitive() {
  const queryClient = useQueryClient()
  const navigate = useNavigate()
  return async (run: () => Promise<unknown>, done: string): Promise<boolean> => {
    try {
      await run()
      toast(done)
      return true
    } catch (e) {
      if (isApiError(e) && e.code === "reauthentication_required") {
        if (await ask(t("reauthenticateConfirm"))) {
          const back = window.location.pathname.slice(base.length - 1) || "/"
          await signOut(queryClient)
          navigate({ to: "/login", search: { redirect: back } })
        }
      } else {
        toast(describe(e), "error")
      }
      return false
    }
  }
}

/** A browser and its system, from its user agent: Chrome on macOS. */
export function deviceName(userAgent: string): string {
  const browser =
    /Edg\//.test(userAgent) ? "Edge" : /Firefox\//.test(userAgent) ? "Firefox" : /Chrome\//.test(userAgent) ? "Chrome" : /Safari\//.test(userAgent) ? "Safari" : ""
  const system = /iPhone|iPad/.test(userAgent)
    ? "iOS"
    : /Android/.test(userAgent)
      ? "Android"
      : /Mac OS X|Macintosh/.test(userAgent)
        ? "macOS"
        : /Windows/.test(userAgent)
          ? "Windows"
          : /Linux/.test(userAgent)
            ? "Linux"
            : ""
  if (browser && system) return t("deviceOn", { browser, system })
  return browser || system || userAgent || t("unknownDevice")
}

const when: FieldMeta = { name: "when", label: "", kind: "datetime", required: false }

export function PasswordCard() {
  const [errors, setErrors] = useState<Record<string, string>>({})
  const change = useMutation({
    mutationFn: (c: { current_password: string; new_password: string }) => account().changePassword(c),
    onSuccess: () => {
      setErrors({})
      toast(t("passwordChanged"))
    },
    onError: (e) => {
      setErrors(fieldErrors(e))
      if (Object.keys(fieldErrors(e)).length === 0) toast(describe(e), "error")
    },
  })
  const field = (name: string): FieldMeta => ({ name, label: "", kind: "text", required: true })
  return (
    <Card>
      <form
        onSubmit={(e) => {
          e.preventDefault()
          const form = new FormData(e.currentTarget)
          change.mutate(
            { current_password: String(form.get("current")), new_password: String(form.get("new")) },
            { onSuccess: () => (e.target as HTMLFormElement).reset() },
          )
        }}
      >
        <CardHeader>
          <CardTitle>{t("password")}</CardTitle>
          <CardDescription>{t("passwordHint")}</CardDescription>
        </CardHeader>
        <CardContent>
          <FieldGroup>
            <Field data-invalid={errors.current_password ? true : undefined}>
              <FieldLabel htmlFor="current">{t("currentPassword")}</FieldLabel>
              <Input id="current" name="current" type="password" autoComplete="current-password" required aria-invalid={!!errors.current_password} />
              {errors.current_password && <FieldError>{fieldMessage(field("current_password"), errors.current_password)}</FieldError>}
            </Field>
            <Field data-invalid={errors.new_password ? true : undefined}>
              <FieldLabel htmlFor="new">{t("newPassword")}</FieldLabel>
              <Input id="new" name="new" type="password" autoComplete="new-password" required aria-invalid={!!errors.new_password} />
              {errors.new_password && <FieldError>{fieldMessage(field("new_password"), errors.new_password)}</FieldError>}
            </Field>
          </FieldGroup>
        </CardContent>
        <CardFooter className="mt-6 justify-end border-t">
          <Button type="submit" disabled={change.isPending}>
            {change.isPending && <Spinner />}
            {t("changePassword")}
          </Button>
        </CardFooter>
      </form>
    </Card>
  )
}

export function DevicesCard() {
  const queryClient = useQueryClient()
  const sensitive = useSensitive()
  const devices = useQuery({ queryKey: ["account", "sessions"], queryFn: () => account().sessions() })
  const refresh = () => queryClient.invalidateQueries({ queryKey: ["account", "sessions"] })
  const others = (devices.data ?? []).filter((d) => !d.current)
  return (
    <Card>
      <CardHeader>
        <CardTitle>{t("devices")}</CardTitle>
        <CardDescription>{t("devicesHint")}</CardDescription>
      </CardHeader>
      <CardContent className="flex flex-col divide-y">
        {devices.isPending && [0, 1].map((i) => <Skeleton key={i} className="my-2 h-12 w-full" />)}
        {devices.isError && <p className="text-sm text-destructive">{describe(devices.error)}</p>}
        {devices.data?.map((d) => (
          <div key={d.id} className="flex items-center gap-3 py-3">
            {/Mobile|iPhone|Android/.test(d.user_agent) ? <Smartphone className="size-5 text-muted-foreground" /> : <Monitor className="size-5 text-muted-foreground" />}
            <div className="min-w-0 flex-1">
              <div className="flex items-center gap-2 text-sm font-medium">
                {deviceName(d.user_agent)}
                {d.current && <Badge variant="secondary">{t("thisDevice")}</Badge>}
              </div>
              <div className="text-xs text-muted-foreground">
                {d.ip_address} · {t("lastSeen", { when: format(when, d.last_seen_at) })}
              </div>
            </div>
            {!d.current && (
              <Button
                variant="ghost"
                size="sm"
                onClick={async () => {
                  await sensitive(() => account().endSession(d.id), t("deviceSignedOut"))
                  refresh()
                }}
              >
                {t("signOut")}
              </Button>
            )}
          </div>
        ))}
      </CardContent>
      {others.length > 0 && (
        <CardFooter className="justify-end border-t">
          <Button
            variant="outline"
            onClick={async () => {
              if (!(await ask(t("signOutOthersConfirm"), { destructive: true }))) return
              await sensitive(() => account().endOtherSessions(), t("othersSignedOut"))
              refresh()
            }}
          >
            <LogOut /> {t("signOutOthers")}
          </Button>
        </CardFooter>
      )}
    </Card>
  )
}

export function EmailCard() {
  const [sent, setSent] = useState("")
  const sensitive = useSensitive()
  const change = useMutation({
    mutationFn: async (email: string) => {
      if (await sensitive(() => account().changeEmail({ email, redirect: `${base}confirm-email` }), t("linkSentShort"))) setSent(email)
    },
  })
  return (
    <Card>
      <form
        onSubmit={(e) => {
          e.preventDefault()
          change.mutate(String(new FormData(e.currentTarget).get("email")))
        }}
      >
        <CardHeader>
          <CardTitle>{t("email")}</CardTitle>
          <CardDescription>{sent ? t("emailLinkSent", { email: sent }) : t("emailHint")}</CardDescription>
        </CardHeader>
        <CardContent>
          <Field>
            <FieldLabel htmlFor="new-email">{t("newEmail")}</FieldLabel>
            <Input id="new-email" name="email" type="email" autoComplete="email" required />
          </Field>
        </CardContent>
        <CardFooter className="mt-6 justify-end border-t">
          <Button type="submit" variant="outline" disabled={change.isPending}>
            {change.isPending && <Spinner />}
            {t("sendLink")}
          </Button>
        </CardFooter>
      </form>
    </Card>
  )
}

/** The theme, light, dark or the system's, kept in this browser. */
export function ThemeCard() {
  const { theme, setTheme } = useTheme()
  const options = [
    { value: "light", label: t("light"), icon: Sun },
    { value: "dark", label: t("dark"), icon: Moon },
    { value: "system", label: t("system"), icon: Monitor },
  ]
  return (
    <Card>
      <CardHeader>
        <CardTitle>{t("theme")}</CardTitle>
        <CardDescription>{t("themeHint")}</CardDescription>
      </CardHeader>
      <CardContent>
        <div role="radiogroup" aria-label={t("theme")} className="grid gap-3 sm:grid-cols-3">
          {options.map((o) => {
            const chosen = (theme ?? "system") === o.value
            return (
              <button
                key={o.value}
                type="button"
                role="radio"
                aria-checked={chosen}
                onClick={() => setTheme(o.value)}
                className={cn(
                  "flex items-center gap-3 rounded-xl border-2 border-border p-4 text-left text-sm font-semibold transition-colors hover:border-primary/50 focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none",
                  chosen && "border-primary bg-primary/5 text-primary",
                )}
              >
                <o.icon className="size-5" />
                {o.label}
              </button>
            )
          })}
        </div>
      </CardContent>
    </Card>
  )
}
